package com.improvedchat.overlay;

import com.improvedchat.model.PlacementMode;
import com.improvedchat.model.TextAlignment;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class OverlayAlignmentTest {
    @Test
    public void calculatesLeftCenterAndRightPositions() {
        assertEquals(4, DynamicChatOverlay.calculateAlignedX(TextAlignment.LEFT, 4, 100, 40));
        assertEquals(34, DynamicChatOverlay.calculateAlignedX(TextAlignment.CENTER, 4, 100, 40));
        assertEquals(64, DynamicChatOverlay.calculateAlignedX(TextAlignment.RIGHT, 4, 100, 40));
    }

    @Test
    public void clampsAlignmentWhenLineExceedsContentWidth() {
        assertEquals(4, DynamicChatOverlay.calculateAlignedX(TextAlignment.LEFT, 4, 100, 140));
        assertEquals(4, DynamicChatOverlay.calculateAlignedX(TextAlignment.CENTER, 4, 100, 140));
        assertEquals(4, DynamicChatOverlay.calculateAlignedX(TextAlignment.RIGHT, 4, 100, 140));
    }

    @Test
    public void preservesLegacyPlacementDefaultsUntilAlignmentIsExplicitlySet() {
        OverlayConfig config = new OverlayConfig();
        assertEquals(TextAlignment.LEFT, config.getTextAlignment());

        config.setPlacementMode(PlacementMode.ABOVE_PLAYER);
        assertEquals(TextAlignment.CENTER, config.getTextAlignment());

        config.setTextAlignment(TextAlignment.RIGHT);
        config.setPlacementMode(PlacementMode.FREE);
        assertEquals(TextAlignment.RIGHT, config.getTextAlignment());
    }
}

package com.improvedchat.overlay;

import com.improvedchat.model.FontSize;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;
import org.junit.BeforeClass;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class ChatRenderUtilsTest {
    private static FontMetrics metrics;

    @BeforeClass
    public static void setUp() {
        BufferedImage image = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        metrics = graphics.getFontMetrics(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
        graphics.dispose();
    }

    @Test
    public void senderTextDecodesAtEscape() {
        assertEquals("Bob@Home", textOf(ChatRenderUtils.parseTextWithIcons(
                "Bob<at>Home", metrics, null, Color.WHITE, FontSize.REGULAR)));
    }

    @Test
    public void messageTextDecodesRuneLiteEscapes() {
        assertEquals("a@<b>@", textOf(ChatRenderUtils.parseTextWithColoursAndIcons(
                "a<at><lt>b<gt><at>", metrics, null, true, Color.WHITE,
                FontSize.REGULAR, null)));
    }

    private static String textOf(List<TextSegment> segments) {
        StringBuilder text = new StringBuilder();
        for (TextSegment segment : segments) {
            if (segment.iconId == -1) {
                text.append(segment.text);
            }
        }
        return text.toString();
    }
}

package com.improvedchat;

import java.lang.reflect.Method;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ChatPresentationConfigTest {
    private final ImprovedChatConfig config = new ImprovedChatConfig() {};

    @Test
    public void configMethodsAreRuneLiteConfigItems() {
        for (Method method : ImprovedChatConfig.class.getDeclaredMethods()) {
            assertTrue(method.isSynthetic() || method.getAnnotation(ConfigItem.class) != null);
        }
    }

    @Test
    public void presentationFeaturesAreOptIn() {
        assertFalse(config.enableCollapsibleChat());
        assertFalse(config.enableChatboxOpacity());
        assertFalse(config.enableDialogueFonts());
    }

    @Test
    public void collapseDefaultsAreStable() {
        assertEquals(ImprovedChatConfig.CollapsedButtonContent.STATIC_TEXT, config.collapsedButtonContent());
        assertEquals("-", config.collapsedButtonContentCustomText());
        assertEquals("+", config.collapsedButtonContentCustomTextHovered());
        assertFalse(config.collapsedButtonTransparent());
    }

    @Test
    public void opacityDefaultsPreserveDialogueBehavior() {
        assertEquals(150, config.chatboxOpacity());
        assertEquals(-1, config.buttonOpacity());
        assertTrue(config.opacityDialogueMenus());
    }

    @Test
    public void dialogueSectionUsesCurrentName() throws Exception {
        ConfigSection section = ImprovedChatConfig.class
            .getField("dialogueFontsSection")
            .getAnnotation(ConfigSection.class);
        assertEquals("Dialogue Text Styling", section.name());
    }
}

package com.improvedchat;

import java.awt.Color;
import net.runelite.api.ChatMessageType;
import org.junit.After;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class MessageColorRuleEngineTest {
    private final ImprovedChatConfig config = new ImprovedChatConfig() {
        @Override
        public boolean enableMessageColorRules() {
            return true;
        }

        @Override
        public String messageColorRules() {
            return "expire::1::flash\nregex:^Boss .* down$::2";
        }

        @Override
        public boolean includePlayerChatInColorRules() {
            return false;
        }

        @Override
        public Color messageRuleColor1() {
            return Color.RED;
        }

        @Override
        public Color messageRuleColor2() {
            return Color.ORANGE;
        }
    };

    @After
    public void tearDown() {
        MessageColorRuleEngine.configure(null);
    }

    @Test
    public void literalRuleReturnsConfiguredColorAndFlash() {
        MessageColorRuleEngine.configure(config);
        assertEquals(Color.RED,
                MessageColorRuleEngine.colorFor("Your boost will expire soon", ChatMessageType.GAMEMESSAGE));
        assertTrue(MessageColorRuleEngine.flashFor(
                "Your boost will expire soon", ChatMessageType.GAMEMESSAGE));
    }

    @Test
    public void regexRuleIsCaseInsensitive() {
        MessageColorRuleEngine.configure(config);
        assertEquals(Color.ORANGE,
                MessageColorRuleEngine.colorFor("boss Vorkath down", ChatMessageType.GAMEMESSAGE));
        assertFalse(MessageColorRuleEngine.flashFor("boss Vorkath down", ChatMessageType.GAMEMESSAGE));
    }

    @Test
    public void playerChatIsExcludedByDefault() {
        MessageColorRuleEngine.configure(config);
        assertNull(MessageColorRuleEngine.colorFor("expire", ChatMessageType.PUBLICCHAT));
        assertFalse(MessageColorRuleEngine.flashFor("expire", ChatMessageType.PUBLICCHAT));
    }

    @Test
    public void plainTextDecodesRuneLiteEscapesAndTags() {
        String encoded = "<col=ff0000>Gzzz<at><at><at> <lt>ok<gt></col>";
        assertEquals("Gzzz@@@ <ok>", MessageColorRuleEngine.plainText(encoded));
        assertEquals("Gzzz@@@ <ok>", OverlayColorRuleEngine.plainText(encoded));
    }
}

